try:
    countries = pycountry.countries.search_fuzzy(country_input)
except Exception:  # pragma: no cover - fuzzy search can raise on no match
    countries = None
if countries:
    return f"COUNTRY_{countries[0].alpha_2}"      # <-- len(countries) is never checked

try:
    countries = pycountry.countries.search_fuzzy(country_input)
except Exception:  # pragma: no cover - fuzzy search can raise on no match
    countries = None

if countries:
    if len(countries) > 1:
        options = ", ".join(f"{c.alpha_2} ({c.name})" for c in countries)
        raise ValueError(
            f"Ambiguous country '{country_input}' matched {len(countries)} countries: "
            f"{options}. Pass an unambiguous ISO 3166-1 alpha-2 code."
        )
    return f"COUNTRY_{countries[0].alpha_2}"

raise ValueError(f"Could not find country: {country_input}")
